def get_all_md_files(workspace):
    """获取所有markdown文件"""
    files = []
    for root, dirs, filenames in os.walk(workspace):
        # 跳过隐藏目录
        dirs[:] = [d for d in dirs if not d.startswith('.') and d != '.git']
        for f in filenames:
            if f.endswith('.md'):
                files.append(os.path.join(root, f))
    return sorted(files)

